import{_ as p,a0 as o,w as r,s as d,ao as l,I as t,x as a,a1 as n,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"我在 Linux 中使用的 5 個 Git 配置 | LCTT x X-CMD","titleTemplate":false,"description":"我在 Linux 中使用的 5 個 Git 配置 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我在 Linux 中使用的 5 個 Git 配置 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我在 Linux 中使用的 5 個 Git 配置 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20220922 5 Git configurations I make on Linux","title":"我在 Linux 中使用的 5 個 Git 配置","tag":"202210","desc":""},"relativePath":"202210/20220922 5 Git configurations I make on Linux.md","filePath":"[post].md"}'),g={name:"202210/20220922 5 Git configurations I make on Linux.md"};function h(u,s,c,k,b,m){const i=o("Link");return r(),d("div",null,[s[29]||(s[29]=l(`<h1 id="我在-linux-中使用的-5-個-git-配置" tabindex="-1">我在 Linux 中使用的 5 個 Git 配置 <a class="header-anchor" href="#我在-linux-中使用的-5-個-git-配置" aria-label="Permalink to “我在 Linux 中使用的 5 個 Git 配置”">​</a></h1><blockquote><p>這份簡要指南能夠幫助你快速開始使用 Git，以及配置一些選項。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202210/11/162338c314ls57bg51hd45.jpg" alt=""></p><p>在 Linux 中設置 Git 十分簡單，但為了獲得完美的配置，我做了以下五件事：</p><ol><li>創建全局配置</li><li>設置默認名稱</li><li>設置默認郵箱地址</li><li>設置默認分支名稱</li><li>設置默認編輯器</li></ol><p>我使用 Git 管理我的代碼、命令列腳本以及文檔版本。這意味着每次我開始一項新的任務，首先我需要創建一個文件目錄並將其添加到 Git 庫中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir newproject</span></span>
<span class="line"><span>$ cd newproject</span></span>
<span class="line"><span>$ git init</span></span></code></pre></div><p>有一些我一直想要的常規設置。不多，但可以避免我每次都進行配置。我喜歡利用 Git 的 <em>全局</em> 配置功能。</p><p>Git 提供了進行手動配置的 <code>git config</code> 命令，但這有一些注意事項。例如，通常你會設置郵箱地址。你可以通過運行 <code>git config user.email 你的郵件地址</code> 命令進行設置。然而，這隻會在你當前所在的 Git 目錄下起作用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git config user.email alan@opensource.com</span></span>
<span class="line"><span>fatal: not in a git directory</span></span></code></pre></div><p>此外，當這個命令在 Git 倉庫中運行時，它只會配置特定的一個倉庫。在新的倉庫中，你不得不重複這個步驟。我可以通過全局配置來避免重複。選項 <code>--global</code> 會指示 Git 將郵箱地址寫入全局配置 <code>~/.gitconfig</code> 文件中，甚至在必要時會創建它：</p><blockquote><p>請記住，波浪線（<code>~</code>）代表你的主文件夾。在我的電腦中它是 <code>/home/alan</code>。</p></blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git config --global user.email alan@opensource.com</span></span>
<span class="line"><span>$ cat ~/.gitconfig</span></span>
<span class="line"><span>[user]</span></span>
<span class="line"><span>        email = alan@opensource.com</span></span></code></pre></div><p>這裏的缺點是，如果你有大量偏好設置，需要輸入很多命令，這將花費大量時間並且很容易出錯。Git 提供了更加快捷有效的方式，可以直接編輯你的全局配置文件——這是我列表中的第一項！</p><h3 id="_1、創建全局配置" tabindex="-1">1、創建全局配置 <a class="header-anchor" href="#_1、創建全局配置" aria-label="Permalink to “1、創建全局配置”">​</a></h3><p>如果你剛開始使用 Git，或許你還沒有該文件。不用擔心，讓我們直接開始。只需要用 <code>--edit</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git config --global --edit</span></span></code></pre></div><p>如果沒有該文件，Git 將會創建一個包含以下內容的新文件，並使用你終端的默認編輯器打開它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># This is Git&#39;s per-user configuration file.</span></span>
<span class="line"><span>[user]</span></span>
<span class="line"><span># Please adapt and uncomment the following lines:</span></span>
<span class="line"><span>#       name = Alan</span></span>
<span class="line"><span>#       email = alan@hopper</span></span>
<span class="line"><span>~</span></span>
<span class="line"><span>~</span></span>
<span class="line"><span>~</span></span>
<span class="line"><span>&quot;~/.gitconfig&quot; 5L, 155B                                     1,1           All</span></span></code></pre></div><p>現在我們已經打開了編輯器，並且 Git 已經在後台創建了全局配置文件，我們可以繼續接下來的設置。</p><h3 id="_2、設置默認名稱" tabindex="-1">2、設置默認名稱 <a class="header-anchor" href="#_2、設置默認名稱" aria-label="Permalink to “2、設置默認名稱”">​</a></h3><p>名字是該文件中的首要條目，讓我們先從它開始。用命令列設置我的名稱是 <code>git config --global user.name &quot;Alan Formy-Duval&quot;</code>。不用在命令列中運行該命令，只需要在配置文件中編輯 <code>name</code> 條目就行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>name = Alan Formy-Duval</span></span></code></pre></div><h3 id="_3、設置默認郵箱地址" tabindex="-1">3、設置默認郵箱地址 <a class="header-anchor" href="#_3、設置默認郵箱地址" aria-label="Permalink to “3、設置默認郵箱地址”">​</a></h3><p>郵箱地址是第二個條目，讓我們添加它。默認情況下，Git 使用你的系統提供的名稱和郵箱地址。如果不正確或者你想要更改，你可以在配置文件中具體説明。事實上，如果你沒有配置這些，Git 在你第一次提交時會友好的提示你：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Committer: Alan &lt;alan@hopper&gt;</span></span>
<span class="line"><span>Your name and email address were configured automatically based</span></span>
<span class="line"><span>on your username and hostname. Please check that they are accurate....</span></span></code></pre></div><p>在命令列中運行 <code>git config --global user.email &quot;alan@opensource.com&quot;</code> 會設置好我的郵箱。同樣，我們在配置文件中編輯 <code>email</code> 條目，提供你的郵箱地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>email = alan@opensource.com</span></span></code></pre></div><p>我喜歡設置的最後兩個設置是默認分支名稱和默認編輯器。當你仍在編輯器中時，需要添加這些指令。</p><h3 id="_4、設置默認分支名稱" tabindex="-1">4、設置默認分支名稱 <a class="header-anchor" href="#_4、設置默認分支名稱" aria-label="Permalink to “4、設置默認分支名稱”">​</a></h3><p>目前有一種趨勢，即不再使用 <code>master</code> 作為默認分支名稱。事實上，在新存儲庫初始化時，Git 將通過友好的消息提示更改默認分支名稱：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git init</span></span>
<span class="line"><span>hint: Using &#39;master&#39; as the name for the initial branch. This default branch name</span></span>
<span class="line"><span>hint: is subject to change. To configure the initial branch name to use in all</span></span>
<span class="line"><span>hint: of your new repositories, which will suppress this warning, call:</span></span>
<span class="line"><span>hint:</span></span>
<span class="line"><span>hint:   git config --global init.defaultBranch &lt;name&gt;</span></span></code></pre></div><p>這個名為 <code>defaultBranch</code> 的指令需要位於一個名為 <code>init</code> 的新部分中。現在普遍接受的是，許多程序員使用 <code>main</code> 這個詞作為他們的默認分支。這是我喜歡使用的。將此部分後跟指令添加到配置中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[init]</span></span>
<span class="line"><span>            defaultBranch = main</span></span></code></pre></div><h3 id="_5、設置默認編輯器" tabindex="-1">5、設置默認編輯器 <a class="header-anchor" href="#_5、設置默認編輯器" aria-label="Permalink to “5、設置默認編輯器”">​</a></h3>`,35)),t("p",null,[s[3]||(s[3]=a("第五個設置是設置默認的編輯器。這是指 Git 將使用的編輯器，用於在你每次將更改提交到存儲庫時輸入你的提交消息。不論是 ",-1)),n(i,{href:"https://opensource.com/article/20/12/gnu-nano"},{default:e(()=>[...s[0]||(s[0]=[a("nano",-1)])]),_:1}),s[4]||(s[4]=a("、",-1)),n(i,{href:"https://opensource.com/resources/what-emacs"},{default:e(()=>[...s[1]||(s[1]=[a("emacs",-1)])]),_:1}),s[5]||(s[5]=a("、",-1)),n(i,{href:"https://opensource.com/article/19/3/getting-started-vim"},{default:e(()=>[...s[2]||(s[2]=[a("vi",-1)])]),_:1}),s[6]||(s[6]=a(" 還是其他編輯器，每個人都有他喜歡的。我喜歡用 vi。添加 ",-1)),s[7]||(s[7]=t("code",null,"core",-1)),s[8]||(s[8]=a(" 部分，並設置 ",-1)),s[9]||(s[9]=t("code",null,"editor",-1)),s[10]||(s[10]=a(" 指令為你喜歡的編輯器。",-1))]),s[30]||(s[30]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[core]</span></span>
<span class="line"><span>            editor = vi</span></span></code></pre></div>`,1)),t("p",null,[s[12]||(s[12]=a("這是最後一項。退出編輯器。Git 在主目錄下保存全局配置文件。如果你再次運行編輯命令，將會看到所有內容。注意配置文件是明文存儲的文本文件，因此它可以很容易使用文本工具查看，如 ",-1)),n(i,{href:"https://opensource.com/article/19/2/getting-started-cat-command"},{default:e(()=>[...s[11]||(s[11]=[a("cat",-1)])]),_:1}),s[13]||(s[13]=a(" 命令。這是我的配置文件內容：",-1))]),s[31]||(s[31]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat ~/.gitconfig</span></span>
<span class="line"><span>[user]</span></span>
<span class="line"><span>        email = alan@opensource.com</span></span>
<span class="line"><span>        name = Alan Formy-Duval</span></span>
<span class="line"><span>[core]</span></span>
<span class="line"><span>        editor = vi</span></span>
<span class="line"><span>[init]</span></span>
<span class="line"><span>        defaultBranch = main</span></span></code></pre></div><p>這是一個簡單的指南，可以讓你快速開始使用 Git 和它的一些配置選項。</p><hr>`,3)),t("p",null,[s[15]||(s[15]=a("via: ",-1)),n(i,{href:"https://opensource.com/article/22/9/git-configuration-linux"},{default:e(()=>[...s[14]||(s[14]=[a("https://opensource.com/article/22/9/git-configuration-linux",-1)])]),_:1})]),t("p",null,[s[20]||(s[20]=a("作者：",-1)),n(i,{href:"https://opensource.com/users/alanfdoss"},{default:e(()=>[...s[16]||(s[16]=[a("Alan Formy-Duval",-1)])]),_:1}),s[21]||(s[21]=a(" 選題：",-1)),n(i,{href:"https://github.com/lkxed"},{default:e(()=>[...s[17]||(s[17]=[a("lkxed",-1)])]),_:1}),s[22]||(s[22]=a(" 譯者：",-1)),n(i,{href:"https://github.com/Donkey-Hao"},{default:e(()=>[...s[18]||(s[18]=[a("Donkey-Hao",-1)])]),_:1}),s[23]||(s[23]=a(" 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[19]||(s[19]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[26]||(s[26]=a("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[24]||(s[24]=[a("LCTT",-1)])]),_:1}),s[27]||(s[27]=a(" 原創編譯，",-1)),n(i,{href:"https://linux.cn/"},{default:e(()=>[...s[25]||(s[25]=[a("Linux中國",-1)])]),_:1}),s[28]||(s[28]=a(" 榮譽推出",-1))])])}const C=p(g,[["render",h]]);export{y as __pageData,C as default};
